import { DEVELOPER, NUMBER, USER } from "./actionTypes";

export const initialState = {
  developers: [],
  user: {},
  arr: [],
};

function reducer(state = initialState, action) {
  switch (action.type) {
    case NUMBER:
      return { ...state, statearr: [...state.arr, action.payload] };
    default:
      return state;
  }
}

export default reducer;
